package run.ikaros.music; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/music/tracks/{trackId}/audio-sources") public class MusicAudioSourceController {private final MusicAudioSourceService service;public MusicAudioSourceController(MusicAudioSourceService s){service=s;}@PostMapping public Mono<MusicAudioSourceView> add(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID trackId,@Valid@RequestBody AddMusicAudioSourceRequest r){return service.add(o,trackId,r);}@GetMapping public Flux<MusicAudioSourceView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID trackId){return service.list(o,trackId);}@GetMapping("/resolve")public Mono<MusicAudioSourceView> resolve(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID trackId,@RequestParam(required=false)UUID sourceId){return service.resolve(o,trackId,sourceId);}}
